/**
 * End-to-end smoke test for every backend endpoint, run against a live server
 * with fake data generated by faker.
 *
 * usage: pnpm --filter backend test:endpoints
 *
 * env:
 *   API_URL         base url including the global prefix (default http://localhost:3001/api/v1)
 *   ADMIN_EMAIL     seeded admin account (default admin@kelontong.test)
 *   ADMIN_PASSWORD  (default Admin12345)
 *
 * note: register/login are throttled to 5 req/min per IP and this script uses
 * 3 of each, so wait a minute between consecutive runs.
 */
import { faker } from "@faker-js/faker";

const API_URL = (process.env.API_URL ?? "http://localhost:3001/api/v1").replace(
  /\/$/,
  "",
);
const ADMIN_EMAIL = process.env.ADMIN_EMAIL ?? "admin@kelontong.test";
const ADMIN_PASSWORD = process.env.ADMIN_PASSWORD ?? "Admin12345";

// minimal cookie jar: paths are ignored, which is fine for a single-origin api
class Session {
  private cookies = new Map<string, string>();

  constructor(readonly label: string) {}

  header(): string | undefined {
    if (this.cookies.size === 0) return undefined;
    return [...this.cookies].map(([k, v]) => `${k}=${v}`).join("; ");
  }

  store(response: Response): void {
    for (const raw of response.headers.getSetCookie()) {
      const [pair, ...attrs] = raw.split(";");
      const index = pair.indexOf("=");
      const name = pair.slice(0, index).trim();
      const value = pair.slice(index + 1).trim();
      const expired = attrs.some((attr) => {
        const [key, val] = attr.trim().split("=");
        const lower = key.toLowerCase();
        return (
          (lower === "max-age" && Number(val) <= 0) ||
          (lower === "expires" && new Date(val).getTime() <= Date.now())
        );
      });
      if (expired || value === "") this.cookies.delete(name);
      else this.cookies.set(name, value);
    }
  }

  get(name: string): string | undefined {
    return this.cookies.get(name);
  }

  set(name: string, value: string): void {
    this.cookies.set(name, value);
  }
}

interface ApiResult<T = any> {
  status: number;
  body: T;
}

async function request<T = any>(
  method: string,
  path: string,
  options: { session?: Session; body?: unknown } = {},
): Promise<ApiResult<T>> {
  const headers: Record<string, string> = { Accept: "application/json" };
  const cookie = options.session?.header();
  if (cookie) headers.Cookie = cookie;
  if (options.body !== undefined) headers["Content-Type"] = "application/json";

  const response = await fetch(`${API_URL}${path}`, {
    method,
    headers,
    body: options.body === undefined ? undefined : JSON.stringify(options.body),
  });
  options.session?.store(response);

  const text = await response.text();
  let body: any = text;
  try {
    body = text ? JSON.parse(text) : null;
  } catch {
    // keep the raw text
  }
  return { status: response.status, body };
}

let passed = 0;
let failed = 0;

class AssertionError extends Error {}

function expect(condition: unknown, message: string): asserts condition {
  if (!condition) throw new AssertionError(message);
}

function expectStatus(result: ApiResult, status: number): void {
  expect(
    result.status === status,
    `expected HTTP ${status}, got ${result.status}: ${JSON.stringify(result.body)}`,
  );
}

function expectError(result: ApiResult, status: number, code: string): void {
  expectStatus(result, status);
  expect(
    result.body?.error?.code === code,
    `expected error code ${code}, got ${JSON.stringify(result.body)}`,
  );
}

async function test(name: string, fn: () => Promise<void>): Promise<void> {
  try {
    await fn();
    passed += 1;
    console.log(`  \x1b[32m✓\x1b[0m ${name}`);
  } catch (error) {
    failed += 1;
    const message = error instanceof Error ? error.message : String(error);
    console.log(`  \x1b[31m✗\x1b[0m ${name}\n      ${message}`);
  }
}

function section(title: string): void {
  console.log(`\n${title}`);
}

function fakeSku(): string {
  return `T-${faker.string.alphanumeric({ length: 8, casing: "upper" })}`;
}

function fakeProduct(categoryId: number) {
  return {
    sku: fakeSku(),
    name: faker.commerce.productName(),
    description: faker.commerce.productDescription(),
    categoryId,
    weight: faker.number.int({ min: 50, max: 5000 }),
    width: faker.number.int({ min: 1, max: 100 }),
    length: faker.number.int({ min: 1, max: 100 }),
    height: faker.number.int({ min: 1, max: 100 }),
    imageUrl: faker.image.url(),
    price: faker.number.int({ min: 1, max: 300 }) * 500,
    stock: faker.number.int({ min: 0, max: 500 }),
    isActive: true,
  };
}

async function main(): Promise<void> {
  console.log(`Testing ${API_URL}`);

  try {
    await fetch(`${API_URL}/health`);
  } catch {
    console.error(`Could not reach ${API_URL}. Is the backend running?`);
    process.exit(1);
  }

  const anon = new Session("anonymous");
  const staff = new Session("staff");
  const admin = new Session("admin");

  const staffUser = {
    email: faker.internet
      .email({ provider: "kelontong.test", allowSpecialCharacters: false })
      .toLowerCase()
      .replace("@", `.${Date.now()}@`),
    name: faker.person.fullName(),
    password: `${faker.internet.password({ length: 10, memorable: false, pattern: /[A-Za-z]/ })}7`,
  };

  let categoryId = 0;
  let product: ReturnType<typeof fakeProduct> & { id: number };

  section("health");
  await test("GET /health reports database up", async () => {
    const res = await request("GET", "/health");
    expectStatus(res, 200);
    expect(res.body.data?.status === "ok", "status should be ok");
    expect(res.body.data?.database === "up", "database should be up");
  });

  section("auth");
  await test("GET /auth/me without a session is 401", async () => {
    expectError(await request("GET", "/auth/me", { session: anon }), 401, "UNAUTHENTICATED");
  });

  await test("POST /auth/register rejects invalid payload", async () => {
    const res = await request("POST", "/auth/register", {
      body: { email: "not-an-email", name: "x", password: "short" },
    });
    expectError(res, 400, "VALIDATION_FAILED");
    const fields = (res.body.error.details ?? []).map((d: any) => d.field);
    for (const field of ["email", "name", "password"]) {
      expect(fields.includes(field), `details should mention ${field}`);
    }
  });

  await test("POST /auth/register creates a STAFF account and sets cookies", async () => {
    const res = await request("POST", "/auth/register", { session: staff, body: staffUser });
    expectStatus(res, 201);
    expect(res.body.data?.email === staffUser.email, "email should match");
    expect(res.body.data?.role === "STAFF", "role should be STAFF");
    expect(!("passwordHash" in res.body.data), "passwordHash must not leak");
    expect(staff.get("access_token"), "access_token cookie should be set");
    expect(staff.get("refresh_token"), "refresh_token cookie should be set");
  });

  await test("POST /auth/register with a taken email is 409", async () => {
    const res = await request("POST", "/auth/register", {
      body: { ...staffUser, email: staffUser.email.toUpperCase() },
    });
    expectError(res, 409, "EMAIL_ALREADY_REGISTERED");
  });

  await test("GET /auth/me returns the registered user", async () => {
    const res = await request("GET", "/auth/me", { session: staff });
    expectStatus(res, 200);
    expect(res.body.data?.email === staffUser.email, "email should match");
  });

  await test("POST /auth/login with a wrong password is 401", async () => {
    const res = await request("POST", "/auth/login", {
      body: { email: ADMIN_EMAIL, password: faker.internet.password() },
    });
    expectError(res, 401, "INVALID_CREDENTIALS");
  });

  await test("POST /auth/login as admin", async () => {
    const res = await request("POST", "/auth/login", {
      session: admin,
      body: { email: ADMIN_EMAIL, password: ADMIN_PASSWORD },
    });
    expectStatus(res, 200);
    expect(res.body.data?.role === "ADMIN", "role should be ADMIN");
  });

  await test("POST /auth/login normalises email case", async () => {
    const res = await request("POST", "/auth/login", {
      session: staff,
      body: { email: `  ${staffUser.email.toUpperCase()} `, password: staffUser.password },
    });
    expectStatus(res, 200);
    expect(res.body.data?.email === staffUser.email, "email should match");
  });

  await test("POST /auth/refresh rotates tokens and rejects the old one", async () => {
    const oldRefresh = staff.get("refresh_token")!;
    // jwt iat has second granularity; wait so the rotated token differs
    await new Promise((resolve) => setTimeout(resolve, 1100));
    const res = await request("POST", "/auth/refresh", { session: staff });
    expectStatus(res, 200);
    expect(res.body.data?.authenticated === true, "authenticated should be true");
    expect(staff.get("refresh_token") !== oldRefresh, "refresh token should rotate");

    const replay = new Session("replay");
    replay.set("refresh_token", oldRefresh);
    expectError(await request("POST", "/auth/refresh", { session: replay }), 401, "UNAUTHENTICATED");
  });

  await test("POST /auth/refresh without a cookie is 401", async () => {
    expectError(await request("POST", "/auth/refresh", { session: anon }), 401, "UNAUTHENTICATED");
  });

  section("categories");
  await test("GET /categories without a session is 401", async () => {
    expectStatus(await request("GET", "/categories", { session: anon }), 401);
  });

  await test("GET /categories lists categories sorted by name", async () => {
    const res = await request("GET", "/categories", { session: staff });
    expectStatus(res, 200);
    const list = res.body.data;
    expect(Array.isArray(list) && list.length > 0, "should return a non-empty array (did you seed?)");
    const names = list.map((c: any) => c.name);
    expect(
      names.every((n: string, i: number) => i === 0 || names[i - 1].localeCompare(n) <= 0),
      "categories should be sorted by name",
    );
    categoryId = faker.helpers.arrayElement(list as { id: number }[]).id;
  });

  section("products: list");
  await test("GET /products returns paginated data with meta", async () => {
    const res = await request("GET", "/products?page=1&pageSize=5", { session: staff });
    expectStatus(res, 200);
    expect(Array.isArray(res.body.data), "data should be an array");
    expect(res.body.data.length <= 5, "should respect pageSize");
    const meta = res.body.meta;
    expect(meta?.page === 1 && meta?.pageSize === 5, "meta should echo pagination");
    expect(typeof meta?.totalItems === "number", "meta.totalItems should be a number");
    expect(
      meta.totalPages === (meta.totalItems === 0 ? 0 : Math.ceil(meta.totalItems / 5)),
      "meta.totalPages should be consistent",
    );
    expect(res.body.data.every((p: any) => p.archivedAt === null), "archived products should be hidden");
  });

  await test("GET /products sorts by price ascending", async () => {
    const res = await request("GET", "/products?sortBy=price&sortOrder=asc&pageSize=20", { session: staff });
    expectStatus(res, 200);
    const prices = res.body.data.map((p: any) => p.price);
    expect(prices.every((p: number, i: number) => i === 0 || prices[i - 1] <= p), "prices should ascend");
  });

  await test("GET /products filters by category and isActive", async () => {
    const res = await request("GET", `/products?categoryId=${categoryId}&isActive=true&pageSize=50`, {
      session: staff,
    });
    expectStatus(res, 200);
    expect(
      res.body.data.every((p: any) => p.categoryId === categoryId && p.isActive === true),
      "every product should match the filters",
    );
  });

  await test("GET /products rejects invalid query params", async () => {
    expectError(await request("GET", "/products?pageSize=101", { session: staff }), 400, "VALIDATION_FAILED");
    expectError(await request("GET", "/products?sortBy=password", { session: staff }), 400, "VALIDATION_FAILED");
  });

  await test("GET /products?archived=only is 403 for staff", async () => {
    expectError(await request("GET", "/products?archived=only", { session: staff }), 403, "FORBIDDEN");
  });

  await test("GET /products?archived=only returns only archived for admin", async () => {
    const res = await request("GET", "/products?archived=only&pageSize=50", { session: admin });
    expectStatus(res, 200);
    expect(res.body.data.every((p: any) => p.archivedAt !== null), "every product should be archived");
  });

  section("products: create");
  await test("POST /products creates a product (staff)", async () => {
    const payload = fakeProduct(categoryId);
    payload.sku = `  ${payload.sku.toLowerCase()} `;
    const res = await request("POST", "/products", { session: staff, body: payload });
    expectStatus(res, 201);
    const created = res.body.data;
    expect(created.sku === payload.sku.trim().toUpperCase(), "sku should be trimmed and upper-cased");
    expect(created.name === payload.name, "name should match");
    expect(created.price === payload.price, "price should match");
    expect(created.categoryId === categoryId && typeof created.categoryName === "string", "category should be embedded");
    product = { ...payload, sku: created.sku, id: created.id };
  });

  await test("GET /products?q=<sku> finds the new product", async () => {
    const res = await request("GET", `/products?q=${encodeURIComponent(product.sku.toLowerCase())}`, {
      session: staff,
    });
    expectStatus(res, 200);
    expect(res.body.data.some((p: any) => p.id === product.id), "search should find the product");
  });

  await test("POST /products with a duplicate sku is 409", async () => {
    const res = await request("POST", "/products", {
      session: staff,
      body: { ...fakeProduct(categoryId), sku: product.sku },
    });
    expectError(res, 409, "SKU_ALREADY_EXISTS");
  });

  await test("POST /products with an unknown category is 422", async () => {
    const res = await request("POST", "/products", { session: staff, body: fakeProduct(999_999) });
    expectError(res, 422, "CATEGORY_NOT_FOUND");
  });

  await test("POST /products rejects invalid and unknown fields", async () => {
    const res = await request("POST", "/products", {
      session: staff,
      body: { ...fakeProduct(categoryId), sku: "bad sku!", price: -1, hacker: true },
    });
    expectError(res, 400, "VALIDATION_FAILED");
  });

  await test("POST /products without a session is 401", async () => {
    expectStatus(await request("POST", "/products", { session: anon, body: fakeProduct(categoryId) }), 401);
  });

  section("products: read & update");
  await test("GET /products/:id returns the product", async () => {
    const res = await request("GET", `/products/${product.id}`, { session: staff });
    expectStatus(res, 200);
    expect(res.body.data?.sku === product.sku, "sku should match");
  });

  await test("GET /products/:id with a non-numeric id is 400", async () => {
    expectStatus(await request("GET", "/products/abc", { session: staff }), 400);
  });

  await test("GET /products/:id with an unknown id is 404", async () => {
    expectError(await request("GET", "/products/999999999", { session: staff }), 404, "PRODUCT_NOT_FOUND");
  });

  await test("PATCH /products/:id partially updates", async () => {
    const changes = {
      name: faker.commerce.productName(),
      price: faker.number.int({ min: 1, max: 300 }) * 500,
      stock: faker.number.int({ min: 0, max: 500 }),
      description: null,
    };
    const res = await request("PATCH", `/products/${product.id}`, { session: staff, body: changes });
    expectStatus(res, 200);
    const updated = res.body.data;
    expect(updated.name === changes.name, "name should update");
    expect(updated.price === changes.price, "price should update");
    expect(updated.stock === changes.stock, "stock should update");
    expect(updated.description === null, "description should be cleared");
    expect(updated.sku === product.sku, "sku should be unchanged");
  });

  await test("PATCH /products/:id rejects null for required fields", async () => {
    const res = await request("PATCH", `/products/${product.id}`, { session: staff, body: { name: null } });
    expectError(res, 400, "VALIDATION_FAILED");
  });

  await test("PATCH /products/:id with an unknown id is 404", async () => {
    const res = await request("PATCH", "/products/999999999", { session: staff, body: { stock: 1 } });
    expectError(res, 404, "PRODUCT_NOT_FOUND");
  });

  section("products: archive & restore");
  await test("DELETE /products/:id is 403 for staff", async () => {
    expectError(await request("DELETE", `/products/${product.id}`, { session: staff }), 403, "FORBIDDEN");
  });

  await test("DELETE /products/:id archives (admin)", async () => {
    const res = await request("DELETE", `/products/${product.id}`, { session: admin });
    expectStatus(res, 204);
  });

  await test("DELETE /products/:id is idempotent", async () => {
    expectStatus(await request("DELETE", `/products/${product.id}`, { session: admin }), 204);
  });

  await test("archived product is hidden from staff", async () => {
    expectError(await request("GET", `/products/${product.id}`, { session: staff }), 404, "PRODUCT_NOT_FOUND");
    const res = await request("PATCH", `/products/${product.id}`, { session: staff, body: { stock: 1 } });
    expectError(res, 404, "PRODUCT_NOT_FOUND");
  });

  await test("archived product is visible to admin", async () => {
    const res = await request("GET", `/products/${product.id}`, { session: admin });
    expectStatus(res, 200);
    expect(res.body.data?.archivedAt !== null, "archivedAt should be set");
  });

  await test("POST /products/:id/restore is 403 for staff", async () => {
    expectError(await request("POST", `/products/${product.id}/restore`, { session: staff }), 403, "FORBIDDEN");
  });

  await test("POST /products/:id/restore restores (admin)", async () => {
    const res = await request("POST", `/products/${product.id}/restore`, { session: admin });
    expectStatus(res, 200);
    expect(res.body.data?.archivedAt === null, "archivedAt should be cleared");
    expectStatus(await request("GET", `/products/${product.id}`, { session: staff }), 200);
  });

  await test("DELETE /products/:id with an unknown id is 404", async () => {
    expectError(await request("DELETE", "/products/999999999", { session: admin }), 404, "PRODUCT_NOT_FOUND");
  });

  section("logout");
  await test("POST /auth/logout clears the session and revokes the refresh token", async () => {
    const refreshToken = staff.get("refresh_token")!;
    const res = await request("POST", "/auth/logout", { session: staff });
    expectStatus(res, 200);
    expect(res.body.data?.authenticated === false, "authenticated should be false");
    expect(!staff.get("access_token") && !staff.get("refresh_token"), "cookies should be cleared");
    expectStatus(await request("GET", "/auth/me", { session: staff }), 401);

    const replay = new Session("replay");
    replay.set("refresh_token", refreshToken);
    expectError(await request("POST", "/auth/refresh", { session: replay }), 401, "UNAUTHENTICATED");
  });

  // leave the shared dataset as we found it
  if (product!) await request("DELETE", `/products/${product.id}`, { session: admin });
  await request("POST", "/auth/logout", { session: admin });

  console.log(`\n${passed} passed, ${failed} failed`);
  process.exit(failed > 0 ? 1 : 0);
}

main().catch((error) => {
  console.error(error);
  process.exit(1);
});
